mapper.select:
select * from ( select a.*,b.machine_name from t_tc_loss_setting a left join T_TC_MACHINE_INFO b on a.machine_id = b.id and b.del_flag = '0' where a.del_flag = '0' and INSTR(sidewall_code, #{sidewallCode}) > 0 and machine_id = #{machineId}
order by a.create_time desc
) t
order by ${orderStr}

select count(1)
from t_tc_loss_setting
where del_flag = '0'
and sidewall_code = #{sidewallCode}
and sidewall_code is null
and machine_id = #{machineId}
and machine_id is null
and id != #{id}

mapper.update:
update t_tc_loss_setting
sidewall_code = #{sidewallCode}, machine_id = #{machineId,jdbcType=VARCHAR}, loss_rate = #{lossRate}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, remark = #{remark},
where id = #{id}

mapper.delete:
update t_tc_loss_setting
set del_flag='1'
where id = #{id}

mapper.update:
merge into t_tc_loss_setting a USING (
select #{MACHINE.sidewallCode,jdbcType=VARCHAR} sidewall_code, #{MACHINE.machineId,jdbcType=DOUBLE} machine_id, #{MACHINE.lossRate,jdbcType=DOUBLE} loss_rate, #{MACHINE.createBy,jdbcType=VARCHAR} create_by, #{MACHINE.createTime,jdbcType=DATE} create_time, #{MACHINE.updateBy,jdbcType=VARCHAR} update_by, #{MACHINE.updateTime,jdbcType=DATE} update_time, #{MACHINE.remark,jdbcType=VARCHAR} remark from dual
) b ON ( ((b.sidewall_code is null and a.sidewall_code is null) or (a.sidewall_code = b.sidewall_code)) and ((b.machine_id is null and a.machine_id is null) or(b.machine_id = a.machine_id)) AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.loss_rate = b.loss_rate, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT ( a.id , a.sidewall_code , a.machine_id , a.loss_rate , a.create_by , a.create_time , a.remark, a.del_flag ) values (SEQ_LOSS_SETTING.NEXTVAL, b.sidewall_code, b.machine_id, b.loss_rate, b.create_by, sysdate, b.remark, '0' )
